package com.savora.api; import com.savora.model.*; import com.savora.repo.*; import com.savora.security.JwtService; import jakarta.validation.Valid; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/auth") public class AuthController { final UserRepo users; final PasswordEncoder encoder; final JwtService jwt; final StringRedisTemplate redis; public AuthController(UserRepo u,PasswordEncoder e,JwtService j,StringRedisTemplate r){users=u;encoder=e;jwt=j;redis=r;} UserDto dto(User u){return new UserDto(u.id,u.name,u.email,u.phone,u.role.name(),u.avatar);} Auth out(User u){String a=jwt.token(u),r=UUID.randomUUID().toString();redis.opsForValue().set("refresh:"+r,u.email,Duration.ofDays(14));return new Auth(a,r,dto(u));} @PostMapping("/register") ResponseEntity<Api<Auth>> register(@Valid @RequestBody Register in){if(users.findByEmail(in.email()).isPresent())throw new IllegalArgumentException("Email is already registered");var u=new User();u.name=in.name();u.email=in.email().toLowerCase();u.phone=in.phone();u.password=encoder.encode(in.password());return ResponseEntity.status(201).body(Api.ok(out(users.save(u))));} @PostMapping("/login") Api<Auth> login(@Valid @RequestBody Credentials in){var u=users.findByEmail(in.email().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!encoder.matches(in.password(),u.password))throw new IllegalArgumentException("Invalid email or password");return Api.ok(out(u));} @PostMapping("/refresh") Api<Auth> refresh(@RequestParam String token){String email=redis.opsForValue().get("refresh:"+token);if(email==null)throw new IllegalArgumentException("Refresh token expired");redis.delete("refresh:"+token);return Api.ok(out(users.findByEmail(email).orElseThrow()));} @PostMapping("/forgot-password") Api<?> forgot(@RequestParam String email){if(users.findByEmail(email).isPresent())redis.opsForValue().set("otp:"+email,"123456",Duration.ofMinutes(10));return Api.ok(Map.of("message","If the account exists, a reset code has been sent."));} }
